import Foundation
import NIO
import NIOWebSocket

// MARK: - Circuit Breaker
enum CircuitState { case closed, open, halfOpen }

class CircuitBreaker {
    private var state: CircuitState = .closed
    private var failureCount: Int = 0
    private let threshold: Int = 5
    private let resetTimeout: TimeInterval = 30
    private var lastFailureTime: Date?
    private let lock = NSLock()

    func recordSuccess() {
        lock.lock()
        defer { lock.unlock() }
        failureCount = 0
        state = .closed
    }

    func recordFailure() {
        lock.lock()
        defer { lock.unlock() }
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= threshold {
            state = .open
        }
    }

    func canExecute() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        switch state {
        case .closed: return true
        case .open:
            if let last = lastFailureTime,
               Date().timeIntervalSince(last) > resetTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen: return true
        }
    }
}

// MARK: - Message Protocol
protocol MessageHandler {
    func handle(_ data: Data, context: ChannelHandlerContext)
}

// MARK: - Codec Registry
class CodecRegistry {
    static let shared = CodecRegistry()
    private var codecs: [String: Any] = [:]

    func register<T>(type: String, codec: T) {
        codecs[type] = codec
    }

    func codec(for type: String) -> Any? {
        return codecs[type]
    }
}

// MARK: - Session State
class SessionState: NSObject, NSSecureCoding {
    static var supportsSecureCoding: Bool { return true }

    var userId: String
    var permissions: [String]
    var metadata: [String: String]

    init(userId: String, permissions: [String], metadata: [String: String] = [:]) {
        self.userId = userId
        self.permissions = permissions
        self.metadata = metadata
    }

    required init?(coder: NSCoder) {
        self.userId = coder.decodeObject(of: NSString.self, forKey: "userId") as? String ?? ""
        self.permissions = coder.decodeObject(of: [NSArray.self, NSString.self], forKey: "permissions") as? [String] ?? []
        self.metadata = coder.decodeObject(of: [NSDictionary.self, NSString.self], forKey: "metadata") as? [String: String] ?? [:]
    }

    func encode(with coder: NSCoder) {
        coder.encode(userId, forKey: "userId")
        coder.encode(permissions, forKey: "permissions")
        coder.encode(metadata, forKey: "metadata")
    }
}

// MARK: - Message Envelope
struct MessageEnvelope {
    let type: String
    let payload: Data
    let sessionToken: Data?
}

// MARK: - WebSocket Handler
class WebSocketHandler: ChannelInboundHandler {
    typealias InboundIn = WebSocketFrame
    typealias OutboundOut = WebSocketFrame

    private let circuitBreaker = CircuitBreaker()
    private var sessionCache: [String: Data] = [:]
    private var sessionCacheOrder: [String] = []
    private static let maxCacheEntries = 1024
    private static let allowedClasses: [AnyClass] = [SessionState.self, NSString.self, NSArray.self, NSDictionary.self]

    private func storeInCache(_ key: String, _ value: Data) {
        if sessionCache[key] == nil {
            sessionCacheOrder.append(key)
            // Evict oldest entries when over the configured limit.
            while sessionCacheOrder.count > Self.maxCacheEntries {
                let oldest = sessionCacheOrder.removeFirst()
                sessionCache.removeValue(forKey: oldest)
            }
        }
        sessionCache[key] = value
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let frame = unwrapInboundIn(data)
        guard case .binary = frame.opcode else { return }

        var frameData = frame.data
        guard let bytes = frameData.readBytes(length: frameData.readableBytes) else { return }
        let rawData = Data(bytes)

        guard circuitBreaker.canExecute() else {
            sendError(context: context, message: "Service unavailable")
            return
        }

        processMessage(rawData, context: context)
    }

    private func processMessage(_ data: Data, context: ChannelHandlerContext) {
        guard let envelope = parseEnvelope(data) else {
            circuitBreaker.recordFailure()
            return
        }

        switch envelope.type {
        case "session.restore":
            restoreSession(envelope, context: context)
        case "session.save":
            saveSession(envelope, context: context)
        case "data.query":
            handleQuery(envelope, context: context)
        default:
            circuitBreaker.recordFailure()
        }
    }

    private func restoreSession(_ envelope: MessageEnvelope, context: ChannelHandlerContext) {
        guard let tokenData = envelope.sessionToken else { return }
        let tokenKey = tokenData.base64EncodedString()

        // Check cache first
        if let cachedData = sessionCache[tokenKey] {
            let session = deserializeSession(cachedData)
            if let session = session {
                circuitBreaker.recordSuccess()
                sendSessionResponse(session, context: context)
                return
            }
        }

        // Deserialize from payload
        let session = deserializeSession(envelope.payload)
        if let session = session {
            storeInCache(tokenKey, envelope.payload)
            circuitBreaker.recordSuccess()
            sendSessionResponse(session, context: context)
        } else {
            circuitBreaker.recordFailure()
        }
    }

    private func deserializeSession(_ data: Data) -> SessionState? {
        // NSKeyedUnarchiver with secure coding enforced
        let unarchiver: NSKeyedUnarchiver
        do {
            unarchiver = try NSKeyedUnarchiver(forReadingFrom: data)
        } catch {
            return nil
        }
        unarchiver.requiresSecureCoding = true
        let session = unarchiver.decodeObject(of: Self.allowedClasses, forKey: NSKeyedArchiveRootObjectKey) as? SessionState
        unarchiver.finishDecoding()
        return session
    }

    private func saveSession(_ envelope: MessageEnvelope, context: ChannelHandlerContext) {
        guard let tokenData = envelope.sessionToken else { return }
        let tokenKey = tokenData.base64EncodedString()
        storeInCache(tokenKey, envelope.payload)
        circuitBreaker.recordSuccess()
    }

    private func handleQuery(_ envelope: MessageEnvelope, context: ChannelHandlerContext) {
        // Safe JSON-only processing
        guard let json = try? JSONSerialization.jsonObject(with: envelope.payload) as? [String: Any] else {
            circuitBreaker.recordFailure()
            return
        }
        circuitBreaker.recordSuccess()
        // Process query...
    }

    private func parseEnvelope(_ data: Data) -> MessageEnvelope? {
        guard data.count > 8 else { return nil }
        let typeLen = Int(data[0]) | (Int(data[1]) << 8)
        guard typeLen > 0, typeLen < 256, data.count > 2 + typeLen + 4 else { return nil }

        let typeData = data[2..<(2 + typeLen)]
        guard let type = String(data: typeData, encoding: .utf8) else { return nil }

        let tokenLenOffset = 2 + typeLen
        let tokenLen = Int(data[tokenLenOffset]) | (Int(data[tokenLenOffset + 1]) << 8)
        let payloadOffset = tokenLenOffset + 2 + tokenLen
        guard payloadOffset <= data.count else { return nil }

        let tokenData: Data? = tokenLen > 0 ? data[(tokenLenOffset + 2)..<payloadOffset] : nil
        let payload = data[payloadOffset...]

        return MessageEnvelope(type: type, payload: Data(payload), sessionToken: tokenData)
    }

    private func sendError(context: ChannelHandlerContext, message: String) {
        let data = message.data(using: .utf8)!
        var buffer = context.channel.allocator.buffer(capacity: data.count)
        buffer.writeBytes(data)
        let frame = WebSocketFrame(fin: true, opcode: .text, data: buffer)
        context.writeAndFlush(wrapOutboundOut(frame), promise: nil)
    }

    private func sendSessionResponse(_ session: SessionState, context: ChannelHandlerContext) {
        let response: [String: Any] = ["userId": session.userId, "permissions": session.permissions]
        guard let jsonData = try? JSONSerialization.data(withJSONObject: response) else { return }
        var buffer = context.channel.allocator.buffer(capacity: jsonData.count)
        buffer.writeBytes(jsonData)
        let frame = WebSocketFrame(fin: true, opcode: .text, data: buffer)
        context.writeAndFlush(wrapOutboundOut(frame), promise: nil)
    }
}
